def rect_union_area(rects={{rects}}):
    events = []
    xs = set()
    for x1, y1, x2, y2 in rects:
        events.append((y1, 1, x1, x2))
        events.append((y2, -1, x1, x2))
        xs.add(x1); xs.add(x2)
    events.sort()
    active = []
    area = 0; prev_y = events[0][0]
    for y, typ, x1, x2 in events:
        if active:
            merged = []
            for a, b in sorted(active):
                if merged and a <= merged[-1][1]:
                    merged[-1] = (merged[-1][0], max(merged[-1][1], b))
                else:
                    merged.append((a, b))
            width = sum(b-a for a, b in merged)
            area += width * (y - prev_y)
        if typ == 1: active.append((x1, x2))
        else: active.remove((x1, x2))
        prev_y = y
    return area
